using WebApplication = Microsoft.AspNetCore.Builder.WebApplication;
using Services = Microsoft.Extensions.DependencyInjection.ServiceCollectionServiceExtensions;
using WorkerBase = Microsoft.Extensions.Hosting.BackgroundService;
using System.Threading;
using System.Threading.Tasks;
var builder = WebApplication.CreateBuilder(args);
Services.AddScoped(builder.Services, typeof(IStore), typeof(Store));
class Worker : WorkerBase { protected override async Task ExecuteAsync(CancellationToken stoppingToken) { try { await RunAsync(stoppingToken); } finally { await CleanupAsync(); } } }

